//! Cargo-driven `netplwiz.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is netplwiz-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6ff50000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7feb8000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7feb8000000u64)),
        o => panic!("netplwiz-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("netplwiz-rust")
        .resource_from_rc("dll/shellext/netplwiz/netplwiz.rc", "netplwiz_res")
        .spec2def("dll/shellext/netplwiz/netplwiz.spec", "netplwiz.dll")
        .spec_stubs()
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/mpr/mpr.spec", "mpr.dll", "mpr")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
